package com.notepocket.app;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.*;
import java.util.*;

/** Offline data remains authoritative until a complete, checked merge can commit atomically. */
final class SyncEngine {
    interface Progress {void show(String message);}
    final Context context;final Store store;final SQLiteDatabase db;final SyncCancel cancel;final Progress progress;
    int conflicts;private int opCount=-1;private final Set<String> changed=new HashSet<>();
    static final class Local {final String entity,kind,key;final JSONObject value;Local(String e,String k,String key,JSONObject v) {entity=e;kind=k;this.key=key;value=v;}}
    SyncEngine(Context c,Store store,SyncCancel cancel,Progress progress) {context=c;this.store=store;db=store.getWritableDatabase();this.cancel=cancel;this.progress=progress;}
    String config(String k) {List<ContentValues> v=store.query("SELECT v FROM sync_config WHERE k=?",k);return v.isEmpty()?"":v.get(0).getAsString("v");}
    void config(String k,String value) {ContentValues v=new ContentValues();v.put("k",k);v.put("v",value);db.insertWithOnConflict("sync_config",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    void bindAccount(JSONObject user) throws Exception {String id=user.getString("permissionId");if(id.isEmpty()) throw new IOException("ไม่พบรหัสบัญชี Drive");String owner=config("owner");if(!owner.isEmpty()&&!owner.equals(id)) throw new IOException("ข้อมูลในเครื่องผูกกับบัญชีอื่นอยู่ กรุณาเลือกบัญชีเดิม");db.beginTransactionNonExclusive();try {config("owner",id);config("email",user.optString("emailAddress"));config("connected","1");db.setTransactionSuccessful();}finally {db.endTransaction();}}
    String sync(SyncRemote remote) throws Exception {
        cancel.check();synchronized(SyncRuntime.EDIT_LOCK) {SyncRuntime.checkEditor();}
        JSONObject user=remote.account().getJSONObject("user");if(!config("owner").equals(user.getString("permissionId"))||!config("connected").equals("1")) throw new IOException("บัญชี Drive ไม่ตรงกับข้อมูลในเครื่อง");
        progress.show("ตรวจข้อมูลในเครื่อง…");Map<String,Local> before=snapshot();capture(before);
        progress.show("ตรวจการเปลี่ยนแปลงจาก Drive…");List<SyncRemote.Item> files=remote.list();Map<String,String> blobs=new HashMap<>();
        for(SyncRemote.Item file:files) {cancel.check();if(file.type.equals("blob-v1")) {if(file.sha.matches("[a-f0-9]{64}")) blobs.putIfAbsent(file.sha,file.id);continue;}if(!file.type.equals("journal-v1")||!store.query("SELECT file_id FROM sync_seen WHERE file_id=?",file.id).isEmpty()) continue;
            JSONObject commit=remote.journal(file.id);if(!"NotePocket-sync-1".equals(commit.getString("format"))) throw new IOException("รูปแบบการซิงก์ไม่รองรับ");JSONArray ops=commit.getJSONArray("ops");if(ops.length()>64) throw new IOException("รายการซิงก์ใหญ่เกินไป");db.beginTransactionNonExclusive();try {for(int i=0;i<ops.length();i++) put(SyncOp.parse(ops.getJSONObject(i)),true);seen(file.id);db.setTransactionSuccessful();}finally {db.endTransaction();}
        }
        validateGraph();progress.show("รวมข้อมูลและเก็บสำเนาที่ขัดแย้ง…");db.beginTransactionNonExclusive();try {resolve();dependencies();db.setTransactionSuccessful();}finally {db.endTransaction();}
        Map<String,SyncOp> heads=allHeads();File stage=new File(context.getCacheDir(),"drive-sync-"+UUID.randomUUID());if(!stage.mkdirs()) throw new IOException("พื้นที่ชั่วคราวไม่เพียงพอ");Map<String,File> staged=new HashMap<>();List<File> created=new ArrayList<>();List<File> removed=new ArrayList<>();
        try {
            int index=0;for(SyncOp op:heads.values()) if(op.value!=null&&(op.kind.equals("doc")||op.kind.equals("font"))) {
                cancel.check();JSONObject v=op.value;String id=v.getString("id"),sha=v.getString("sha");long size=v.getLong("size");progress.show("ตรวจไฟล์ "+(++index)+" · "+v.getString("name"));
                File own=new File(context.getFilesDir(),id),source=null;Local local=before.get(op.entity);if(own.isFile()&&local!=null&&sha.equals(local.value.optString("sha"))) source=own;
                if(source==null&&own.isFile()&&own.length()==size&&sha.equals(SyncJson.fileHash(own,cancel))) source=own;
                if(source==null) {for(Local candidate:before.values()) if((candidate.kind.equals("doc")||candidate.kind.equals("font"))&&sha.equals(candidate.value.optString("sha"))) {File f=new File(context.getFilesDir(),candidate.value.getString("id"));if(f.isFile()) {source=f;break;}}}
                if(source!=null&&source.length()!=size) throw new IOException("ขนาดไฟล์จาก Drive ไม่ตรงกัน");
                if(!blobs.containsKey(sha)) {if(source==null) throw new IOException("ไฟล์ยังส่งขึ้น Drive ไม่ครบ กรุณาซิงก์จากเครื่องต้นทางอีกครั้ง");progress.show("ส่งไฟล์ · "+v.getString("name"));blobs.put(sha,remote.uploadBlob(sha,source));}
                if(source==null||!source.equals(own)) {File prepared=staged.get(sha);if(prepared==null) {prepared=new File(stage,sha);if(source!=null) copy(source,prepared,size);else {progress.show("ดาวน์โหลด · "+v.getString("name"));remote.downloadBlob(blobs.get(sha),prepared,size);}if(prepared.length()!=size||!sha.equals(SyncJson.fileHash(prepared,cancel))) throw new IOException("ตรวจสอบไฟล์จาก Drive ไม่ผ่าน");staged.put(sha,prepared);}if(op.kind.equals("font")) android.graphics.Typeface.createFromFile(prepared);}
            }
            publish(remote);
            synchronized(SyncRuntime.EDIT_LOCK) {
                SyncRuntime.checkEditor();cancel.check();if(!config("connected").equals("1")||!config("owner").equals(user.getString("permissionId"))) throw new InterruptedIOException("Disconnected");Map<String,Local> current=snapshot();if(!same(before,current)) {capture(current);throw new IOException("มีการแก้ไขระหว่างซิงก์ เก็บข้อมูลไว้แล้ว กรุณากดซิงก์อีกครั้ง");}
                progress.show("บันทึกข้อมูลที่ตรวจครบแล้ว…");db.beginTransactionNonExclusive();try {
                    for(SyncOp op:heads.values()) if(op.value!=null&&(op.kind.equals("doc")||op.kind.equals("font"))) {String id=op.value.getString("id");File destination=new File(context.getFilesDir(),id);Local old=before.get(op.entity);boolean valid=destination.isFile()&&(old!=null&&op.value.getString("sha").equals(old.value.optString("sha"))||old==null&&op.value.getLong("size")==destination.length()&&op.value.getString("sha").equals(SyncJson.fileHash(destination,cancel)));if(!valid) {if(destination.exists()&&old!=null) throw new IOException("ไฟล์ในเครื่องมีข้อมูลต่างกัน จึงยังไม่เขียนทับ");File source=staged.get(op.value.getString("sha"));if(source==null) throw new IOException("ไฟล์ไม่ครบ");File complete=new File(stage,"ready-"+UUID.randomUUID());copy(source,complete,op.value.getLong("size"));if(!complete.renameTo(destination)) throw new IOException("ย้ายไฟล์ที่ตรวจครบแล้วไม่ได้");created.add(destination);}}
                    apply(heads,before,removed);cancel.check();config("last_success",Long.toString(System.currentTimeMillis()));db.setTransactionSuccessful();created.clear();
                } finally {db.endTransaction();}
            }
            for(File f:removed) f.delete();Fonts.trimMemory();return "ซิงก์ข้อมูลและไฟล์ครบแล้ว"+(conflicts>0?" · เก็บสำเนาขัดแย้ง "+conflicts+" รายการ":"");
        } finally {for(File f:created) f.delete();Backup.deleteTree(stage);}
    }
    private void seen(String id) {ContentValues v=new ContentValues();v.put("file_id",id);db.insertWithOnConflict("sync_seen",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
    private void copy(File a,File b,long size) throws Exception {try(InputStream in=new FileInputStream(a);OutputStream out=new FileOutputStream(b)) {byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1) {cancel.check();total+=n;if(total>size) throw new IOException("File size changed");out.write(buffer,0,n);}if(total!=size) throw new IOException("File incomplete");}}
    private Map<String,Local> snapshot() throws Exception {
        Map<String,Local> result=new LinkedHashMap<>();Map<String,JSONArray> attachments=new HashMap<>();for(ContentValues link:store.query("SELECT note_id,doc_id FROM note_docs ORDER BY note_id,doc_id")) attachments.computeIfAbsent(link.getAsString("note_id"),k->new JSONArray()).put(link.getAsString("doc_id"));
        try(Cursor c=db.rawQuery("SELECT * FROM notes",null)) {while(c.moveToNext()) {cancel.check();String id=c.getString(c.getColumnIndexOrThrow("id")),sid=c.getString(c.getColumnIndexOrThrow("sync_id"));if(sid.isEmpty()) {sid=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("sync_id",sid);db.update("notes",v,"id=?",new String[]{id});}JSONObject v=new JSONObject();for(String key:new String[]{"title","body","rich","folder","tables","soap"}) v.put(key,c.getString(c.getColumnIndexOrThrow(key)));for(String key:new String[]{"pinned","deleted","updated"}) v.put(key,c.getLong(c.getColumnIndexOrThrow(key)));v.put("docs",attachments.getOrDefault(id,new JSONArray()));add(result,new Local("n-"+sid,"note",id,v));}}
        for(ContentValues f:store.query("SELECT name FROM folders")) {String name=f.getAsString("name");add(result,new Local("l-"+SyncJson.hash(name),"folder",name,new JSONObject().put("name",name)));}
        for(String kind:new String[]{"doc","font"}) for(ContentValues row:store.query("SELECT * FROM "+(kind.equals("doc")?"docs":"fonts"))) {cancel.check();String id=row.getAsString("id");File file=new File(context.getFilesDir(),id);String sha;List<ContentValues> cached=store.query("SELECT * FROM sync_blob_local WHERE id=?",id);
            if(file.isFile()) {if(!cached.isEmpty()&&file.length()==cached.get(0).getAsLong("size")&&file.lastModified()==cached.get(0).getAsLong("modified")) sha=cached.get(0).getAsString("sha");else {sha=SyncJson.fileHash(file,cancel);ContentValues cv=new ContentValues();cv.put("id",id);cv.put("sha",sha);cv.put("size",file.length());cv.put("modified",file.lastModified());db.insertWithOnConflict("sync_blob_local",null,cv,SQLiteDatabase.CONFLICT_REPLACE);}if(file.length()!=row.getAsLong("size")) throw new IOException("ขนาดไฟล์ในเครื่องเปลี่ยนไป");}
            else {SyncOp known=alive((kind.equals("doc")?"d-":"f-")+id);if(known==null) throw new IOException("ไฟล์ในเครื่องไม่ครบ กรุณาตรวจไฟล์แนบ");sha=known.value.getString("sha");}
            JSONObject v=new JSONObject().put("id",id).put("name",row.getAsString("name")).put("size",row.getAsLong("size")).put("sha",sha);if(kind.equals("doc")) v.put("mime",row.getAsString("mime"));add(result,new Local((kind.equals("doc")?"d-":"f-")+id,kind,id,v));}
        for(ContentValues page:store.query("SELECT doc_id,page FROM page_notes UNION SELECT doc_id,page FROM page_ink UNION SELECT doc_id,page FROM page_text ORDER BY doc_id,page")) {String doc=page.getAsString("doc_id");int number=page.getAsInteger("page");ContentValues note=store.page(doc,number);JSONObject v=new JSONObject().put("doc",doc).put("page",number).put("ink",store.drawing(doc,number)).put("boxes",store.textBoxes(doc,number)).put("body",note.getAsString("body")).put("bookmarked",note.getAsInteger("bookmarked"));add(result,new Local(SyncOp.pageEntity(doc,number),"page",doc+":"+number,v));}
        for(ContentValues reading:store.query("SELECT * FROM reading")) {String doc=reading.getAsString("doc_id");add(result,new Local("r-"+doc,"reading",doc,new JSONObject().put("doc",doc).put("page",reading.getAsInteger("page"))));}return result;
    }
    private void add(Map<String,Local> result,Local local) throws Exception {new SyncOp("check",local.entity,local.kind,Collections.emptyList(),local.value,0);result.put(local.entity,local);if(result.size()>50000) throw new IOException("ข้อมูลเกินขอบเขตการซิงก์รุ่นนี้");}
    private boolean same(Map<String,Local> a,Map<String,Local> b) throws Exception {if(!a.keySet().equals(b.keySet())) return false;for(String k:a.keySet()) if(!SyncJson.fingerprint(a.get(k).value).equals(SyncJson.fingerprint(b.get(k).value))) return false;return true;}
    private void capture(Map<String,Local> locals) throws Exception {db.beginTransactionNonExclusive();try {
        Map<String,ContentValues> bindings=new HashMap<>();for(ContentValues row:store.query("SELECT * FROM sync_bindings")) bindings.put(row.getAsString("entity"),row);
        for(Local local:locals.values()) {ContentValues binding=bindings.remove(local.entity);String fingerprint=SyncJson.fingerprint(local.value);if(binding==null||!fingerprint.equals(binding.getAsString("fingerprint"))) {List<String> parents=binding==null||binding.getAsString("head").isEmpty()?Collections.emptyList():Collections.singletonList(binding.getAsString("head"));SyncOp op=new SyncOp(UUID.randomUUID().toString(),local.entity,local.kind,parents,local.value,System.currentTimeMillis());put(op,false);bind(local,op);}}
        for(ContentValues old:bindings.values()) if(!old.getAsString("fingerprint").equals("~")) {SyncOp op=new SyncOp(UUID.randomUUID().toString(),old.getAsString("entity"),old.getAsString("kind"),Collections.singletonList(old.getAsString("head")),null,System.currentTimeMillis());put(op,false);bind(new Local(op.entity,op.kind,old.getAsString("local_key"),null),op);}db.setTransactionSuccessful();
    } finally {db.endTransaction();}}
    private void bind(Local local,SyncOp op) throws Exception {ContentValues v=new ContentValues();v.put("entity",op.entity);v.put("kind",op.kind);v.put("local_key",local.key);v.put("fingerprint",op.fingerprint());v.put("head",op.rev);db.insertWithOnConflict("sync_bindings",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    private SyncOp get(String rev) throws Exception {List<ContentValues> r=store.query("SELECT json FROM sync_ops WHERE rev=?",rev);return r.isEmpty()?null:SyncOp.parse(new JSONObject(r.get(0).getAsString("json")));}
    private void put(SyncOp op,boolean uploaded) throws Exception {String json=SyncJson.canonical(op.json());List<ContentValues> existing=store.query("SELECT json FROM sync_ops WHERE rev=?",op.rev);if(!existing.isEmpty()) {if(!existing.get(0).getAsString("json").equals(json)) throw new IOException("ข้อมูลซิงก์มีรหัสซ้ำแต่เนื้อหาต่างกัน");if(uploaded) {ContentValues acknowledged=new ContentValues();acknowledged.put("uploaded",1);db.update("sync_ops",acknowledged,"rev=?",new String[]{op.rev});}return;}if(opCount<0) opCount=store.query("SELECT COUNT(*) AS n FROM sync_ops").get(0).getAsInteger("n");if(opCount++>=100000) throw new IOException("ประวัติซิงก์ครบขอบเขต 100000 รายการ");ContentValues v=new ContentValues();v.put("rev",op.rev);v.put("entity",op.entity);v.put("kind",op.kind);v.put("json",json);v.put("label",op.label());v.put("time",op.time);v.put("deleted",op.value==null?1:0);v.put("uploaded",uploaded?1:0);db.insertOrThrow("sync_ops",null,v);for(String parent:op.parents) {ContentValues p=new ContentValues();p.put("rev",op.rev);p.put("parent",parent);db.insertOrThrow("sync_parents",null,p);}changed.add(op.entity);}
    private void validateGraph() throws Exception {
        List<ContentValues> rows=store.query("SELECT o.rev,o.entity,o.kind,p.parent FROM sync_ops o LEFT JOIN sync_parents p ON p.rev=o.rev");if(rows.size()>300000) throw new IOException("ประวัติการซิงก์ใหญ่เกินไป");Map<String,String> entities=new HashMap<>(),kinds=new HashMap<>();Map<String,List<String>> graph=new HashMap<>();for(ContentValues r:rows) {String rev=r.getAsString("rev");entities.put(rev,r.getAsString("entity"));kinds.put(rev,r.getAsString("kind"));graph.computeIfAbsent(rev,k->new ArrayList<>());if(r.getAsString("parent")!=null) graph.get(rev).add(r.getAsString("parent"));}
        for(String rev:graph.keySet()) for(String p:graph.get(rev)) if(!entities.containsKey(p)) throw new IOException("Drive ยังส่งประวัติมาไม่ครบ กรุณาลองซิงก์อีกครั้ง");else if(!entities.get(rev).equals(entities.get(p))||!kinds.get(rev).equals(kinds.get(p))) throw new IOException("สายประวัติไม่ถูกต้อง");
        Map<String,Integer> degree=new HashMap<>();Map<String,List<String>> children=new HashMap<>();ArrayDeque<String> queue=new ArrayDeque<>();for(String rev:graph.keySet()) {degree.put(rev,graph.get(rev).size());if(graph.get(rev).isEmpty()) queue.add(rev);for(String p:graph.get(rev)) children.computeIfAbsent(p,k->new ArrayList<>()).add(rev);}int visited=0;while(!queue.isEmpty()) {String p=queue.remove();visited++;for(String child:children.getOrDefault(p,Collections.emptyList())) if(degree.compute(child,(k,n)->n-1)==0) queue.add(child);}if(visited!=graph.size()) throw new IOException("ประวัติวนซ้ำ จึงยังไม่รวมข้อมูล");
    }
    private List<SyncOp> heads(String entity) throws Exception {List<SyncOp> result=new ArrayList<>();for(ContentValues r:store.query("SELECT o.json FROM sync_ops o WHERE o.entity=? AND NOT EXISTS(SELECT 1 FROM sync_parents p WHERE p.parent=o.rev) ORDER BY o.rev",entity)) result.add(SyncOp.parse(new JSONObject(r.getAsString("json"))));return result;}
    private Map<String,SyncOp> allHeads() throws Exception {Map<String,SyncOp> result=new LinkedHashMap<>();for(ContentValues r:store.query("SELECT DISTINCT entity FROM sync_ops ORDER BY entity")) {List<SyncOp> h=heads(r.getAsString("entity"));if(h.size()!=1) throw new IOException("ยังรวมประวัติไม่ครบ");result.put(h.get(0).entity,h.get(0));}return result;}
    private SyncOp alive(String entity) throws Exception {List<ContentValues> r=store.query("SELECT json FROM sync_ops WHERE entity=? AND deleted=0 ORDER BY rev DESC LIMIT 1",entity);return r.isEmpty()?null:SyncOp.parse(new JSONObject(r.get(0).getAsString("json")));}
    private void resolve() throws Exception {for(ContentValues row:store.query("SELECT DISTINCT entity FROM sync_ops ORDER BY entity")) {cancel.check();List<SyncOp> h=heads(row.getAsString("entity"));if(h.size()<2) continue;h.sort((a,b)->{if(a.value==null&&b.value!=null) return -1;if(a.value!=null&&b.value==null) return 1;if(a.kind.equals("reading")&&a.time!=b.time) return Long.compare(a.time,b.time);return a.rev.compareTo(b.rev);});SyncOp winner=h.get(h.size()-1);List<String> parents=new ArrayList<>();long time=0;for(SyncOp op:h) {parents.add(op.rev);time=Math.max(time,op.time);if(op!=winner&&op.value!=null&&!op.fingerprint().equals(winner.fingerprint())&&!Arrays.asList("folder","reading").contains(op.kind)) {fork(op,"conflict-"+SyncJson.hash(op.entity+":"+op.rev),true);conflicts++;}}
            Collections.sort(parents);put(new SyncOp("merge-"+SyncJson.hash(winner.entity+parents),winner.entity,winner.kind,parents,winner.value,time),false);
        }}
    private void fork(SyncOp op,String suffix,boolean conflict) throws Exception {
        String caption=conflict?" · สำเนาขัดแย้ง":" · กู้คืน";JSONObject value=SyncJson.copy(op.value);long time=op.time;
        if(op.kind.equals("note")) {String entity="n-"+suffix;value.put("title",value.getString("title")+caption);value.put("deleted",0);put(new SyncOp("fork-"+SyncJson.hash(entity+op.rev),entity,"note",Collections.emptyList(),value,time),false);}
        else if(op.kind.equals("doc")||op.kind.equals("font")) {String id=suffix;value.put("id",id);value.put("name",value.getString("name")+caption);put(new SyncOp("fork-"+SyncJson.hash(id+op.rev),(op.kind.equals("doc")?"d-":"f-")+id,op.kind,Collections.emptyList(),value,time),false);}
        else if(op.kind.equals("page")) {String doc=value.getString("doc");SyncOp source=alive("d-"+doc);if(source==null) throw new IOException("ไม่พบเอกสารของสำเนาขัดแย้ง");JSONObject file=SyncJson.copy(source.value);file.put("id",suffix);file.put("name",file.getString("name")+caption+" หน้า "+(value.getInt("page")+1));put(new SyncOp("fork-doc-"+SyncJson.hash(suffix),"d-"+suffix,"doc",Collections.emptyList(),file,time),false);value.put("doc",suffix);put(new SyncOp("fork-page-"+SyncJson.hash(suffix),SyncOp.pageEntity(suffix,value.getInt("page")),"page",Collections.emptyList(),value,time),false);JSONObject reading=new JSONObject().put("doc",suffix).put("page",value.getInt("page"));put(new SyncOp("fork-read-"+SyncJson.hash(suffix),"r-"+suffix,"reading",Collections.emptyList(),reading,time),false);}
    }
    void restoreCopy(String rev) throws Exception {SyncOp op=get(rev);if(op==null||op.value==null||!Arrays.asList("note","doc","page").contains(op.kind)) throw new IOException("กู้คืนรายการนี้ไม่ได้");db.beginTransactionNonExclusive();try {fork(op,"restored-"+UUID.randomUUID(),false);db.setTransactionSuccessful();}finally {db.endTransaction();}}
    private void dependencies() throws Exception {for(int pass=0;pass<4;pass++) {Map<String,SyncOp> h=allHeads();boolean added=false;int fonts=0;for(SyncOp op:new ArrayList<>(h.values())) if(op.value!=null) {JSONObject v=op.value;if(op.kind.equals("font")) fonts++;if(op.kind.equals("note")) {JSONArray docs=v.getJSONArray("docs");for(int i=0;i<docs.length();i++) added|=require("d-"+docs.getString(i),op.rev,h);String name=v.getString("folder"),entity="l-"+SyncJson.hash(name);SyncOp folder=h.get(entity);if(folder==null||folder.value==null) {List<String> parents=folder==null?Collections.emptyList():Collections.singletonList(folder.rev);SyncOp restored=new SyncOp("restore-folder-"+SyncJson.hash(entity+op.rev+parents),entity,"folder",parents,new JSONObject().put("name",name),op.time);put(restored,false);h.put(entity,restored);added=true;}}
                if(op.kind.equals("page")) {added|=require("d-"+v.getString("doc"),op.rev,h);for(TextBox box:TextBox.decode(v.getString("boxes"))) if(!Arrays.asList("sans","serif","mono").contains(box.font)) added|=require("f-"+box.font,op.rev,h);}}
            if(fonts>30) throw new IOException("ฟอนต์จากทุกเครื่องรวมเกิน 30 ฟอนต์ กรุณาจัดการฟอนต์ก่อน");if(!added) return;}throw new IOException("ความสัมพันธ์ของข้อมูลยังไม่ครบ");}
    private boolean require(String entity,String cause,Map<String,SyncOp> h) throws Exception {SyncOp head=h.get(entity);if(head!=null&&head.value!=null) return false;SyncOp previous=alive(entity);if(previous==null) throw new IOException("เอกสารหรือฟอนต์ต้นทางยังซิงก์มาไม่ครบ");List<String> parents=head==null?Collections.emptyList():Collections.singletonList(head.rev);SyncOp restored=new SyncOp("restore-"+SyncJson.hash(entity+cause+parents),entity,previous.kind,parents,previous.value,previous.time);put(restored,false);h.put(entity,restored);return true;}
    private void publish(SyncRemote remote) throws Exception {
        List<ContentValues> pending=store.query("SELECT rev,json FROM sync_ops WHERE uploaded=0 ORDER BY CASE kind WHEN 'doc' THEN 0 WHEN 'font' THEN 0 WHEN 'folder' THEN 1 WHEN 'note' THEN 2 ELSE 3 END,rowid");int at=0;
        while(at<pending.size()) {cancel.check();JSONArray ops=new JSONArray();List<String> revs=new ArrayList<>();int size=0;while(at<pending.size()&&revs.size()<64) {ContentValues row=pending.get(at);String json=row.getAsString("json");int bytes=json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(size+bytes>6000000&&!revs.isEmpty()) break;ops.put(new JSONObject(json));revs.add(row.getAsString("rev"));size+=bytes;at++;}progress.show("ส่งการเปลี่ยนแปลง "+at+" / "+pending.size());String file=remote.publish(new JSONObject().put("format","NotePocket-sync-1").put("ops",ops));db.beginTransactionNonExclusive();try {for(String rev:revs) {ContentValues v=new ContentValues();v.put("uploaded",1);db.update("sync_ops",v,"rev=?",new String[]{rev});}seen(file);db.setTransactionSuccessful();}finally {db.endTransaction();}}
    }
    private void apply(Map<String,SyncOp> heads,Map<String,Local> before,List<File> removed) throws Exception {
        // Files and folders first, then notes, then page overlays and read positions.
        List<SyncOp> sorted=new ArrayList<>(heads.values());sorted.sort(Comparator.comparingInt(o->o.kind.equals("doc")||o.kind.equals("font")||o.kind.equals("folder")?0:o.kind.equals("note")?1:2));
        for(SyncOp op:sorted) {cancel.check();JSONObject v=op.value;Local old=before.get(op.entity);String key=old==null?"":old.key;boolean unchanged=old!=null&&SyncJson.fingerprint(old.value).equals(op.fingerprint());
            if(!unchanged) switch(op.kind) {
                case "folder":if(v!=null) {key=v.getString("name");store.createFolder(key);}break;
                case "doc":case "font": {String table=op.kind.equals("doc")?"docs":"fonts",id=v==null?(old==null?op.entity.substring(2):old.key):v.getString("id");key=id;if(v==null) {if(old!=null) {if(op.kind.equals("doc")) store.eraseDoc(id);else db.delete("fonts","id=?",new String[]{id});removed.add(new File(context.getFilesDir(),id));}}else {ContentValues cv=new ContentValues();for(String field:new String[]{"id","name"}) cv.put(field,v.getString(field));cv.put("size",v.getLong("size"));if(op.kind.equals("doc")) cv.put("mime",v.getString("mime"));db.insertWithOnConflict(table,null,cv,SQLiteDatabase.CONFLICT_REPLACE);}break;}
                case "note": {String sid=op.entity.substring(2);List<ContentValues> existing=store.query("SELECT id FROM notes WHERE sync_id=?",sid);if(v==null) {if(!existing.isEmpty()) store.eraseNote(existing.get(0).getAsLong("id"));}else {ContentValues cv=new ContentValues();for(String field:new String[]{"title","body","rich","folder","tables","soap"}) cv.put(field,v.getString(field));cv.put("pinned",v.getInt("pinned"));cv.put("deleted",v.getInt("deleted"));cv.put("updated",v.optLong("updated",op.time));cv.put("sync_id",sid);store.createFolder(v.getString("folder"));long id;if(existing.isEmpty()) id=db.insertOrThrow("notes",null,cv);else {id=existing.get(0).getAsLong("id");db.update("notes",cv,"id=?",new String[]{""+id});}key=""+id;db.delete("note_docs","note_id=?",new String[]{key});JSONArray docs=v.getJSONArray("docs");for(int i=0;i<docs.length();i++) {ContentValues link=new ContentValues();link.put("note_id",id);link.put("doc_id",docs.getString(i));db.insertOrThrow("note_docs",null,link);}}break;}
                case "page": {JSONObject source=v==null?(old==null?null:old.value):v;if(source!=null) {String doc=source.getString("doc");int page=source.getInt("page");key=doc+":"+page;if(v==null) {for(String table:new String[]{"page_notes","page_ink","page_text"}) db.delete(table,"doc_id=? AND page=?",new String[]{doc,""+page});}else {ContentValues note=new ContentValues();note.put("doc_id",doc);note.put("page",page);note.put("body",v.getString("body"));note.put("bookmarked",v.getInt("bookmarked"));store.savePage(note);store.saveDrawing(doc,page,v.getString("ink"));store.saveText(doc,page,v.getString("boxes"));}}break;}
                case "reading": {String doc=op.entity.substring(2);key=doc;if(v==null||heads.get("d-"+doc)==null||heads.get("d-"+doc).value==null) db.delete("reading","doc_id=?",new String[]{doc});else store.remember(doc,v.getInt("page"));break;}
            }
            bind(new Local(op.entity,op.kind,key,v),op);
        }
        for(SyncOp op:sorted) if(op.kind.equals("folder")&&op.value==null) {SyncOp prior=alive(op.entity);if(prior!=null) {String name=prior.value.getString("name");if(!name.equals("ทั่วไป")&&store.query("SELECT id FROM notes WHERE folder=? LIMIT 1",name).isEmpty()) db.delete("folders","name=?",new String[]{name});}}
    }
}
